// 检查血压是否超过阈值
const bpData = $input.first().json;
const entries = bpData.entries || bpData;
const alerts = [];

if (Array.isArray(entries) && entries.length > 0) {
  const latest = entries[0];
  const systolic = Number(latest.systolic);
  const diastolic = Number(latest.diastolic);

  if (systolic > 160) {
    alerts.push({
      type: 'HIGH_BP_SYSTOLIC',
      severity: systolic > 180 ? 'CRITICAL' : 'WARNING',
      metric: '收缩压',
      value: systolic,
      threshold: 160,
      unit: 'mmHg',
      detail: `收缩压 ${systolic} mmHg 超过阈值 160 mmHg${systolic > 180 ? '（危险！）' : '（偏高）'}`
    });
  }
  if (diastolic > 100) {
    alerts.push({
      type: 'HIGH_BP_DIASTOLIC',
      severity: diastolic > 110 ? 'CRITICAL' : 'WARNING',
      metric: '舒张压',
      value: diastolic,
      threshold: 100,
      unit: 'mmHg',
      detail: `舒张压 ${diastolic} mmHg 超过阈值 100 mmHg`
    });
  }
}

return [{ json: { alerts, bpChecked: true, timestamp: new Date().toISOString() } }];

// 检查血钾是否超过阈值
const labData = $input.first().json;
const results = labData.results || labData;
const prevAlerts = $('检查血压阈值').first().json.alerts || [];
const alerts = [...prevAlerts];

if (Array.isArray(results)) {
  // 查找血钾结果（biomarker_id 或名称包含 potassium/钾）
  const potassiumResults = results.filter(r => {
    const name = (r.biomarker_name || '').toLowerCase();
    return name.includes('potassium') || name.includes('钾') || r.biomarker_id === 'potassium';
  });

  if (potassiumResults.length > 0) {
    const latest = potassiumResults[0];
    const value = Number(latest.value_numeric);

    if (value > 5.0) {
      alerts.push({
        type: 'HIGH_POTASSIUM',
        severity: value > 6.0 ? 'CRITICAL' : 'WARNING',
        metric: '血钾',
        value: value,
        threshold: 5.0,
        unit: latest.unit_ucum || 'mmol/L',
        detail: `血钾 ${value} mmol/L 超过阈值 5.0 mmol/L${value > 6.0 ? '（危险！需立即就医）' : '（偏高）'}`
      });
    }
  }
}

return [{ json: { alerts, timestamp: new Date().toISOString() } }];

// 构建告警消息
const alerts = $input.first().json.alerts;
const timestamp = $input.first().json.timestamp;
const time = new Date(timestamp).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });

const hasCritical = alerts.some(a => a.severity === 'CRITICAL');
const emoji = hasCritical ? '🚨' : '⚠️';
const title = hasCritical ? '紧急健康告警' : '健康告警';

// 构建告警详情
const alertDetails = alerts.map(a => {
  const icon = a.severity === 'CRITICAL' ? '🔴' : '🟡';
  return `${icon} **${a.metric}**: ${a.value} ${a.unit} (阈值: ${a.threshold})`;
}).join('\n');

const suggestions = alerts.map(a => {
  if (a.type === 'HIGH_BP_SYSTOLIC' || a.type === 'HIGH_BP_DIASTOLIC') {
    return '- 静坐休息，避免剧烈活动\n- 如持续偏高，联系医生调整降压药\n- 减少盐分摄入';
  }
  if (a.type === 'HIGH_POTASSIUM') {
    return '- 立即停止高钾食物（香蕉、橙子、土豆等）\n- 如 > 6.0 需立即就医\n- 联系医生检查是否需要降钾药物';
  }
  return '- 请关注相关指标';
}).join('\n');

const markdown = {
  title: `${emoji} ${title}`,
  text: `## ${emoji} ${title}\n**时间**: ${time}\n\n### 告警详情\n${alertDetails}\n\n### 建议措施\n${suggestions}\n\n---\n*health-mcp 自动告警系统*`
};

return [{ json: { markdown } }];
